<script setup>import{useConfirm}from'../../composables/useConfirm';import Modal from'./Modal.vue';import Button from'./Button.vue';const{state,finish}=useConfirm()</script><template><Modal :model-value="state.open" :title="state.title" size="sm" @update:model-value="v=>!v&&finish(false)"><p class="message">{{state.message}}</p><template #footer><Button variant="secondary" @click="finish(false)">{{state.cancelText}}</Button><Button :variant="state.tone==='danger'?'danger':'primary'" @click="finish(true)">{{state.confirmText}}</Button></template></Modal></template><style scoped>.message{font-size:13px;line-height:1.7;color:var(--text-secondary);white-space:pre-wrap}</style>